-- Catalog fingerprint. Every category reads pg_catalog (readable by any role); none reads information_schema,
-- whose views hide objects the connecting role has no privilege on. A verifier role with NO table privileges
-- therefore produces the same fingerprint as the owner. Do not reintroduce information_schema here.
select 'columns' cat, count(*) n, md5(string_agg(c.relname||'.'||a.attname||':'||format_type(a.atttypid,a.atttypmod)||':'||(not a.attnotnull)::text||':'||coalesce(pg_get_expr(d.adbin,d.adrelid),''), '|' order by c.relname, a.attname)) h from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname='public' and c.relkind in ('r','p','v','f') and a.attnum>0 and not a.attisdropped union all
select 'constraints', count(*), md5(string_agg(cl.relname||'.'||co.conname||':'||pg_get_constraintdef(co.oid), '|' order by cl.relname, co.conname)) from pg_constraint co join pg_class cl on cl.oid=co.conrelid join pg_namespace n on n.oid=cl.relnamespace where n.nspname='public' union all
select 'indexes', count(*), md5(string_agg(indexname||':'||indexdef, '|' order by indexname)) from pg_indexes where schemaname='public' union all
select 'policies', count(*), md5(string_agg(tablename||'.'||policyname||':'||cmd||':'||array_to_string(roles,',')||':'||coalesce(qual,'')||':'||coalesce(with_check,''), '|' order by tablename, policyname)) from pg_policies where schemaname='public' union all
select 'functions', count(*), md5(string_agg(p.proname||'('||pg_get_function_identity_arguments(p.oid)||'):'||p.prosecdef::text||':'||coalesce(p.proacl::text,''), '|' order by p.proname, pg_get_function_identity_arguments(p.oid))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e') union all
select 'rls', count(*), md5(string_agg(relname||':'||relrowsecurity::text||':'||relforcerowsecurity::text, '|' order by relname)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and relkind='r' union all
select 'table_acl_innhouse', count(*), md5(string_agg(relname||':'||regexp_replace(coalesce(relacl::text,''),'m/','/','g'), '|' order by relname)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and relkind='r' and relname in ('houses','creators','house_members','channels','stations');
